#include "core/strategy/Presets.h"

#include "core/classify/Catalog.h"

#include <algorithm>

// The embedded preset files (generated by cmake/EmbedText.cmake, one per data/strategies file).
namespace icd::core::strategy::embedded {
    std::string_view mixed();
    std::string_view development();
    std::string_view archive();
    std::string_view photos();
    std::string_view video();
    std::string_view defrag_only();
    std::string_view hot_zone();
    std::string_view cold_zone();
    std::string_view directory_clustering();
    std::string_view type_segregation();
    std::string_view size_placement();
    std::string_view access_time();
    std::string_view free_space();
    std::string_view read_ahead();
} // namespace icd::core::strategy::embedded

namespace icd::core::strategy {

    std::vector<std::string_view> builtinPresetJson() {
        using namespace embedded;
        return {mixed(),
                development(),
                archive(),
                photos(),
                video(),
                defrag_only(),
                hot_zone(),
                cold_zone(),
                directory_clustering(),
                type_segregation(),
                size_placement(),
                access_time(),
                free_space(),
                read_ahead()};
    }

    const std::vector<ZoneScript>& builtinPresets() {
        static const std::vector<ZoneScript> presets = [] {
            std::vector<ZoneScript> out;
            for (const std::string_view json : builtinPresetJson()) {
                out.push_back(parseZoneScript(json, classify::builtinCatalog()));
            }
            return out;
        }();
        return presets;
    }

    std::optional<std::size_t> builtinPresetIndex(std::string_view id) {
        const auto& presets = builtinPresets();
        const auto it = std::ranges::find(presets, id, &ZoneScript::id);
        return it == presets.end() ? std::nullopt : std::optional(static_cast<std::size_t>(it - presets.begin()));
    }

} // namespace icd::core::strategy
